export function TouchControls({ enabled, regime, source, onFire, onWeapon, onTarget, weapon, onFoot, onInteractPress, onInteractRelease, onDrop }): React.ReactElement | null {
  const [fireHeld, setFireHeld] = React.useState(false);
  const [interactHeld, setInteractHeld] = React.useState(false);
  const interactHeldRef = React.useRef(false);
  interactHeldRef.current = interactHeld;

  // clear on disable/unmount (no change)
  React.useEffect(() => { ... }, [enabled, source]);

  const prevRegimeRef = React.useRef<Regime | null>(null);
  React.useEffect(() => {
    const prev = prevRegimeRef.current;
    prevRegimeRef.current = regime;
    if (prev === null) return;
    if (prev === 'surface') source.clear(); // leaving the on-foot layout
    else if (regime === 'atmosphere') source.setChannel({ boost: false });
    else if (regime === 'space') source.setChannel({ vtol: false });
    else source.clear(); // entering the surface
  }, [regime, source]);

  // when the on-foot layout unmounts (regime flip / onFoot flip / disable),
  // end any INTERACT hold in progress — an unmounted button never fires onRelease,
  // and a mining channel must not be left open to a key nobody is holding.
  const onFootActive = regime === 'surface' && !!onFoot && !!onInteractPress;
  React.useEffect(() => {
    if (!onFootActive) return;
    return () => {
      if (interactHeldRef.current) onInteractRelease?.();
    };
  }, [onFootActive, onInteractRelease]);

  if (!enabled) return null;

  if (regime === 'surface') {
    if (!onFoot) return null;
    return ( ...on-foot layout... );
  }
  const atmosphere = regime === 'atmosphere';
