  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'e' && e.key !== 'E') return;
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA')) return;
      if (anySurfaceOpen()) return; // TASK-53: any open surface is modal (ESC only)
      if (dockedIndicator()) {
        const shipId = selfShipIdRef.current;
        if (!shipId) return;
        clientRef.current?.send('exit_ship', { shipId });
        return;
      }
      // TASK-38: long-press E (hold, not tap) — the first keydown starts
      // the hold (dispatch → 'mine-start' for deposits); auto-repeat
      // re-sends are ignored (the server is idempotent either way).
      // E up (onKeyUp) releases it. The registry is the only place an
